package com.bank.core;

public class Account {
    // PRIVATE: not inherited → cannot be overridden.
    private String tag() { return "ACCOUNT-tag"; }
    public String showTag() { return tag(); } // binds to Account.tag() within Account

    // STATIC: belongs to class → can be HIDDEN, not overridden.
    public static String type() { return "ACCOUNT-type"; }

    // INSTANCE (non-static, non-private): can be truly OVERRIDDEN.
    public String label() { return "ACCOUNT-label"; }
}
