package com.bank.core;

public class Savings extends Account {
    // A NEW private method, unrelated to Account.tag() (no override).
    private String tag() { return "SAVINGS-tag"; }

    // HIDES Account.type() — resolved by reference type at compile time.
    public static String type() { return "SAVINGS-type"; }

    // TRUE OVERRIDE — dynamic dispatch at runtime.
    @Override
    public String label() { return "SAVINGS-label"; }
}
