package com.bank.core;

import java.util.logging.*;

public class OverrideHidingDemo {
    private static final Logger log = Logger.getLogger("BankLog");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Savings savings = new Savings();
        Account ref = savings; // same object, parent-typed reference

        // PRIVATE: parent's showTag still uses Account.tag() → no override effect.
        log.info(() -> "showTag() via Savings → " + savings.showTag());

        // STATIC: resolved by REFERENCE TYPE at compile time (hiding).
        log.warning(() -> "Account.type() → " + Account.type());
        log.warning(() -> "Savings.type() → " + Savings.type());
        log.warning(() -> "ref.type() (ref is Account-typed) → " + ref.type()); // ACCOUNT-type

        // INSTANCE: true override → dynamic dispatch picks Savings regardless of ref type.
        log.info(() -> "ref.label() (true override) → " + ref.label()); // SAVINGS-label
    }
}
